"""Companion metadata for IQ WAV recordings generated by PT2VHF SDR Tool.

The sidecar is an unsigned observation, not proof of RF provenance or modulation.
It marks center/sample-rate drift and VOX gating as unsuitable for continuous
channelization. No personal IDs, callsigns or sample content are stored.
"""
from __future__ import annotations

import hashlib
import json
import math
import os
import tempfile
from datetime import datetime, timezone
from pathlib import Path


def _utc():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def sha256_file(path: Path) -> str:
    """Hash a closed WAV in bounded memory. This verifies integrity, not RF origin."""
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for chunk in iter(lambda: stream.read(4 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def sidecar_path(wav: Path) -> Path:
    return Path(str(wav) + ".iq.json")


class IQCaptureProvenance:
    """Mutate only while Engine._lock is held; finalize after WAV is closed."""

    def __init__(self, wav: Path, *, center_hz: float, sample_rate: int,
                 vfo_hz: float, source: str, mode: str, vox: bool):
        if not math.isfinite(float(center_hz)) or sample_rate <= 0:
            raise ValueError("IQ provenance needs valid center and sample rate")
        self.wav = Path(wav)
        self.center_hz = float(center_hz)
        self.sample_rate = int(sample_rate)
        self.last_center = float(center_hz)
        self.last_rate = int(sample_rate)
        self.vfo_hz = float(vfo_hz)
        self.source = str(source)
        self.mode = str(mode)
        self.vox = bool(vox)
        self.started_utc = _utc()
        self.frames = 0
        self.blocks = 0
        self.center_changes = 0
        self.rate_changes = 0
        self.center_events: list[dict] = []
        self.skipped_blocks = 0

    def observe(self, center_hz: float, sample_rate: int, count: int, wrote: bool):
        if count < 0:
            raise ValueError("IQ block size cannot be negative")
        center_hz = float(center_hz)
        sample_rate = int(sample_rate)
        if abs(center_hz - self.last_center) > 0.5:
            self.center_changes += 1
            if len(self.center_events) < 20:
                self.center_events.append({
                    "recorded_frame_offset": self.frames,
                    "from_hz": self.last_center,
                    "to_hz": center_hz,
                })
            self.last_center = center_hz
        if sample_rate != self.last_rate:
            self.rate_changes += 1
            self.last_rate = sample_rate
        self.blocks += 1
        if wrote:
            self.frames += count
        else:
            self.skipped_blocks += 1

    def pending_report(self) -> dict:
        """Written when capture starts, so a crash cannot resemble legacy WAV."""
        report = self.report(0)
        report.update(
            schema_version=2,
            capture_state="recording",
            completed_utc=None,
            completed=False,
            wav_sha256=None,
            wav_size_bytes=None,
            suitable_for_continuous_channelization=False,
            invalid_reasons=["capture_not_completed"],
        )
        return report

    def final_report(self, wav_frames: int) -> dict:
        """Called after WAV close; missing digest leaves the pending marker intact."""
        file_size = self.wav.stat().st_size
        checksum = sha256_file(self.wav)
        if file_size != self.wav.stat().st_size:
            raise RuntimeError("WAV changed during SHA-256 calculation")
        report = self.report(wav_frames)
        report.update(
            schema_version=2,
            capture_state="complete",
            wav_sha256=checksum,
            wav_size_bytes=file_size,
        )
        return report

    def report(self, wav_frames: int) -> dict:
        reasons = []
        if self.vox:
            reasons.append("vox_gated_iq")
        if self.center_changes:
            reasons.append("center_frequency_changed")
        if self.rate_changes:
            reasons.append("sample_rate_changed")
        if self.frames < 2048:
            reasons.append("too_few_samples")
        if self.frames != wav_frames:
            reasons.append("wav_frame_count_mismatch")
        return {
            "schema_version": 1,
            "capture_kind": "pt2vhf_raw_iq",
            "wav_name": self.wav.name,
            "started_utc": self.started_utc,
            "completed_utc": _utc(),
            "completed": True,
            "source_name": self.source,
            "sample_rate_hz": self.sample_rate,
            "center_hz": self.center_hz,
            "vfo_hz_at_start": self.vfo_hz,
            "receiver_mode_at_start": self.mode,
            "iq_vox": self.vox,
            "dc_removed_per_processing_block": True,
            "written_frames": self.frames,
            "blocks_observed": self.blocks,
            "blocks_skipped": self.skipped_blocks,
            "center_change_count": self.center_changes,
            "sample_rate_change_count": self.rate_changes,
            "center_change_events": self.center_events,
            "suitable_for_continuous_channelization": not reasons,
            "invalid_reasons": reasons,
            "rf_provenance_verified": False,
            "mode_label_verified": False,
        }


def write_sidecar(wav: Path, report: dict):
    """Create/update a small JSON sidecar atomically. Does not touch IQ samples."""
    out = sidecar_path(wav)
    out.parent.mkdir(parents=True, exist_ok=True)
    tmp = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=out.parent,
                                         prefix=".iqmeta_", suffix=".tmp",
                                         delete=False) as f:
            tmp = Path(f.name)
            json.dump(report, f, indent=2, ensure_ascii=False, allow_nan=False)
            f.write("\n")
        os.replace(tmp, out)
    finally:
        if tmp is not None:
            tmp.unlink(missing_ok=True)
